execute_js.body:
() => {
 const nav = document.querySelector('nav[aria-label="Main navigation"]');
 const sidebar = nav.parentElement;
 const labels = ['New Chat','Search','Tools','Extensions','Projects'];
 const menus = labels.every(label => [...nav.querySelectorAll('button')].some(b => b.ariaLabel === label && b.getBoundingClientRect().height > 0));
 const recents = [...sidebar.querySelectorAll('span')].find(e => e.textContent === 'Recents');
 const panel = sidebar.querySelector('[data-sidebar-panel]');
 const expectedPanel = 'cowork';
 const panelCorrect = expectedPanel === 'chat' ? !panel : panel?.dataset.sidebarPanel === expectedPanel && !!(recents.compareDocumentPosition(panel) & Node.DOCUMENT_POSITION_FOLLOWING);
 return {mode: 'Cowork', menus, recents: !!recents, panelCorrect, passed: menus && !!recents && panelCorrect};
}

